-- Demo catalogue for the Project Estimator, DEMO tenants only (is_demo = true).
-- Run AFTER 0133_item_types_and_bom.sql and AFTER seed-estimator-demo.sql.
-- (0133 adds item types and BOM lines; seed-estimator-demo.sql adds the template that names
-- these products. Both live under supabase/migrations/ and scripts/.)
-- Idempotent: a product whose SKU the tenant already has is skipped, a BOM line that is
-- already there is skipped, and a rerun only re-adds the rolled-up cost to the three kits.
-- GENERATED by scripts/gen-estimator-products-demo-seed.ts from
-- src/lib/estimator/demoProducts.ts; do not edit by hand, change that file and regenerate.
--
-- What it does, per demo tenant:
--   1. turns the Products module on (tenants.features.products = true);
--   2. adds 21 illustrative Saudi precast products in SAR with an item type and a cost price:
--      hollow-core slab and wall panels (solid, sandwich insulated) per m2, precast column and
--      beam per m3, stair flight per no., parapet per lm, grout and sealant, steel connection
--      plates, transport per trip, crane and erection crew per day (services), a mould set
--      (a tool), and the materials the kits are made of. They get the next free PRD-#### numbers;
--   3. adds the three BOM kits' components (the mould set as a USED line, which is listed
--      but not costed) and writes each kit's rolled-up cost into its cost_price, by the same
--      rule the product page's "Apply to product cost" uses: qty x (1 + scrap%) x component
--      cost, each line rounded to 2 decimals, used lines excluded (KIT-WALL-M2 223.68, KIT-BOUNDARY-M2 68.07, KIT-FRAME-M3 1385);
--   4. links the demo sample estimate's lines ("Sample villa, Riyadh (illustrative)") to these products,
--      so the lines show the product, its reference and its kit components.
-- Everything is illustrative: placeholder costs, not a real price or any company's method.

do $seed$
declare
  t uuid;
  base int;
begin
  for t in select id from tenants where is_demo = true loop
    update tenants set features = coalesce(features, '{}'::jsonb) || '{"products": true}'::jsonb where id = t;

    select coalesce(max(nullif(regexp_replace(ref, '\D', '', 'g'), '')::int), 0) into base
    from products where tenant_id = t and ref ~ '^PRD-\d+$';

    with todo as (
      select v.*, row_number() over (order by v.n) as rn
      from (values
    (1, 'PC-HCS-200', 'Hollow-core slab 200 mm', 'm2', 'finished_product', 'Prestressed hollow-core floor and roof slab, 200 mm, per m² of slab.', 190, 145),
    (2, 'PC-WALL-SOLID', 'Solid precast wall panel 150 mm', 'm2', 'finished_product', 'Reinforced solid wall panel, 150 mm, per m² of wall.', 275, 210),
    (3, 'PC-WALL-SAND', 'Sandwich insulated wall panel 200 mm', 'm2', 'finished_product', 'Two concrete leaves around 50 mm insulation, per m² of wall.', 445, 340),
    (4, 'PC-COL', 'Precast column', 'm3', 'finished_product', 'Reinforced precast column, per m³ of concrete.', 1900, 1450),
    (5, 'PC-BEAM', 'Precast beam', 'm3', 'finished_product', 'Reinforced precast beam, per m³ of concrete.', 1780, 1350),
    (6, 'PC-STAIR', 'Precast stair flight', 'Nos', 'finished_product', 'Straight precast stair flight with landing, per flight.', 8100, 6200),
    (7, 'PC-PARAPET', 'Precast parapet panel', 'lm', 'finished_product', 'Roof parapet panel, per linear metre.', 405, 310),
    (8, 'CN-GROUT', 'Non-shrink grout, 25 kg bag', 'Bag', 'consumable', 'Cementitious non-shrink grout for panel and column joints.', 52, 38),
    (9, 'CN-SEALANT', 'Joint sealant', 'lm', 'consumable', 'Weather sealant with backing rod, per linear metre of joint.', 20, 14),
    (10, 'BO-PLATE', 'Steel connection plate', 'Nos', 'bought_out_component', 'Galvanised steel connection plate with anchors.', 118, 85),
    (11, 'SV-TRANSPORT', 'Transport to site (per trip)', 'Trip', 'service', 'Low-bed trailer trip from the factory to site, up to 25 t.', 2300, 1800),
    (12, 'SV-ERECT', 'Crane and erection crew (per day)', 'Day', 'service', 'Mobile crane with operator and a four-person erection crew, per day.', 4200, 3200),
    (13, 'SV-CAST-LABOUR', 'Casting labour (per hour)', 'Hr', 'service', 'Factory casting and finishing labour.', 26, 18),
    (14, 'TL-MOULD-SET', 'Wall panel mould set', 'Set', 'tool_equipment', 'Steel mould set for wall panels. Used by the panel kits, not consumed by them.', null::numeric, 48000),
    (15, 'RM-CONCRETE', 'Precast concrete C40', 'm3', 'raw_material', 'Ready-mixed C40 concrete for the casting yard.', null::numeric, 330),
    (16, 'RM-REBAR', 'Reinforcement steel, cut and bent', 'Kg', 'raw_material', 'Reinforcement bar, cut and bent to schedule.', null::numeric, 3.2),
    (17, 'RM-INSUL', 'Insulation board 50 mm', 'm2', 'raw_material', 'Rigid insulation board for sandwich panels.', null::numeric, 38),
    (18, 'BO-CONNECTOR', 'Sandwich panel connector', 'Nos', 'bought_out_component', 'Thermal connector tying the two leaves of a sandwich panel.', null::numeric, 18),
    (19, 'KIT-WALL-M2', 'Villa wall panel kit (per m²)', 'm2', 'bom_kit', 'Insulated external wall panel: concrete, reinforcement, insulation, connectors and casting labour per m² of wall.', null::numeric, null::numeric),
    (20, 'KIT-BOUNDARY-M2', 'Boundary wall panel kit (per m²)', 'm2', 'bom_kit', 'Solid boundary wall panel: concrete, reinforcement and casting labour per m² of wall.', null::numeric, null::numeric),
    (21, 'KIT-FRAME-M3', 'Frame mix: columns and beams (per m³)', 'm3', 'bom_kit', 'One m³ of frame concrete as 35% columns and 65% beams.', null::numeric, null::numeric)
      ) as v(n, sku, name, uom, item_type, description, list_price, cost_price)
      where not exists (select 1 from products p where p.tenant_id = t and p.sku = v.sku)
    )
    insert into products (tenant_id, ref, name, sku, uom, item_type, description, list_price, cost_price, cost_price_as_of, tax_percent, status)
    select t, 'PRD-' || lpad((base + todo.rn)::text, 4, '0'), todo.name, todo.sku, todo.uom, todo.item_type, todo.description,
           todo.list_price, todo.cost_price, case when todo.cost_price is null then null else current_date end, 15, 'active'
    from todo;

    insert into product_bom_lines (tenant_id, parent_product_id, component_product_id, qty, uom, scrap_pct, line_kind, sort_order, note)
    select t, k.id, c.id, v.qty, v.uom, v.scrap_pct, v.line_kind, v.sort_order, v.note
    from (values
    ('KIT-WALL-M2', 'RM-CONCRETE', 0.2, 'm3', 3, 'consumed', 1, '200 mm leaf-equivalent'),
    ('KIT-WALL-M2', 'RM-REBAR', 20, 'Kg', 5, 'consumed', 2, null::text),
    ('KIT-WALL-M2', 'RM-INSUL', 1, 'm2', 5, 'consumed', 3, null::text),
    ('KIT-WALL-M2', 'BO-CONNECTOR', 2, 'Nos', 0, 'consumed', 4, null::text),
    ('KIT-WALL-M2', 'SV-CAST-LABOUR', 0.7, 'Hr', 0, 'consumed', 5, null::text),
    ('KIT-WALL-M2', 'TL-MOULD-SET', 1, 'Set', 0, 'used', 6, 'Tool: listed, not costed'),
    ('KIT-BOUNDARY-M2', 'RM-CONCRETE', 0.1, 'm3', 3, 'consumed', 7, null::text),
    ('KIT-BOUNDARY-M2', 'RM-REBAR', 8, 'Kg', 5, 'consumed', 8, null::text),
    ('KIT-BOUNDARY-M2', 'SV-CAST-LABOUR', 0.4, 'Hr', 0, 'consumed', 9, null::text),
    ('KIT-BOUNDARY-M2', 'TL-MOULD-SET', 1, 'Set', 0, 'used', 10, 'Tool: listed, not costed'),
    ('KIT-FRAME-M3', 'PC-COL', 0.35, 'm3', 0, 'consumed', 11, null::text),
    ('KIT-FRAME-M3', 'PC-BEAM', 0.65, 'm3', 0, 'consumed', 12, null::text)
    ) as v(kit, component, qty, uom, scrap_pct, line_kind, sort_order, note)
    join products k on k.tenant_id = t and k.sku = v.kit
    join products c on c.tenant_id = t and c.sku = v.component
    on conflict (parent_product_id, component_product_id) do nothing;

    -- The kits' rolled-up cost, written to cost_price like "Apply to product cost".
    update products k set cost_price = r.total, cost_price_as_of = current_date, updated_at = now()
    from (
      select l.parent_product_id as pid, round(sum(round(l.qty * (1 + l.scrap_pct / 100) * c.cost_price, 2)), 2) as total
      from product_bom_lines l
      join products c on c.id = l.component_product_id and c.tenant_id = l.tenant_id
      where l.tenant_id = t and l.line_kind = 'consumed' and c.cost_price is not null
      group by l.parent_product_id
    ) r
    where k.id = r.pid and k.tenant_id = t and k.sku in ('KIT-WALL-M2', 'KIT-BOUNDARY-M2', 'KIT-FRAME-M3');

    -- Link the sample estimate's product lines to these products (and keep their reference).
    update estimate_lines el
    set product_id = p.id,
        custom_data = coalesce(el.custom_data, '{}'::jsonb) || case when p.ref is null then '{}'::jsonb else jsonb_build_object('product_ref', p.ref) end
    from estimates e, products p
    where el.tenant_id = t and e.id = el.estimate_id and e.tenant_id = t
      and e.name = 'Sample villa, Riyadh (illustrative)' and e.standard_quote_id is null
      and el.source = 'rule' and el.product_id is null
      and p.tenant_id = t and p.status = 'active' and p.sku = el.custom_data->>'sku';
  end loop;
end
$seed$;
